def transform(grid):
    bg = grid[0][0]
    rows, cols = len(grid), len(grid[0])
    seen = set()
    blocks = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in seen and grid[nr][nc] != bg:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            r0 = min(x for x, y in comp)
            c0 = min(y for x, y in comp)
            blocks.append((r0, c0, grid[r0][c0]))
    out = [[blocks[0][2]] * 4 for _ in range(4)]
    for r, c, color in blocks:
        for rr in range(4):
            for cc in range(4):
                v = grid[r + rr][c + cc]
                if v != color:
                    out[rr][cc] = v
    return out
